// DevTools Memory panel, snapshot sorted by 'Shallow Size' descending.
// Top rows: (string) 480 B, Array 312 B, Object 200 B ...
// Conclusion: "no leak". Why is this wrong?

function retainedSize(edges, shallow, root, target) {
  // BUG: sums the shallow size of every node reachable FROM target,
  // counting shared nodes that the root (or others) still keep alive.
  const seen = new Set();
  const q = [target];
  while (q.length) {
    const n = q.shift();
    if (seen.has(n)) continue;
    seen.add(n);
    for (const m of edges[n]) q.push(m);
  }
  let total = 0;
  for (const n of seen) total += shallow[n];
  return total;
}

