const LIMIT = 1_000_000_000; // 1 GB container limit

function memoryHealth() {
  const m = process.memoryUsage();
  // alert if we're using too much memory
  const usedPct = m.heapUsed / LIMIT;
  return {
    ok: usedPct < 0.9,
    usedPct,
    detail: `heapUsed ${(m.heapUsed / 1e6).toFixed(0)} MB`,
  };
}

function takeSnapshotIfHot() {
  // grab a heap snapshot when memory is high, to find the leak
  if (!memoryHealth().ok) {
    require('v8').writeHeapSnapshot();
  }
}
